var C4_CSS = `.c4sum{font-size:17px;line-height:1.5;margin:10px 0 4px;max-width:820px}.c4fw ul{list-style:none;padding:0;margin:0;display:grid;gap:8px}.c4fw li{padding:10px 14px;border-radius:12px;background:var(--soft,#f5f3ef)}.c4fw li b{margin-right:6px}
.c4lbl{display:inline-block;width:max-content;max-width:100%;align-self:flex-start;font-size:12px;font-weight:700;padding:3px 8px;border-radius:999px;background:#0f3d2e;color:#fff;margin:0 6px 6px 0}.c4lbl.sc{background:#7a3d00}
.c4ph{position:absolute;right:12px;top:64px;z-index:3;font:600 13px system-ui;background:rgba(0,0,0,.72);color:#fff;border:0;border-radius:999px;padding:8px 12px;min-height:36px;cursor:pointer}.c4ph:focus-visible{outline:3px solid #ffd27a;outline-offset:2px}
td.win{font-weight:700;background:rgba(31,122,90,.12)}.c4fac td,.c4fac th{text-align:center}.c4fac td:first-child,.c4fac th:first-child{text-align:left}
.c4row{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.c4row a,.c4row button{display:inline-flex;align-items:center;min-height:44px;padding:0 16px;border-radius:999px;border:1px solid var(--line,#ddd);background:var(--card,#fff);color:inherit;font:600 14px system-ui;text-decoration:none;cursor:pointer}
.c4hom{margin:8px 0;padding:10px 14px;border-radius:12px;border:1px dashed var(--line,#ccc);font-size:15px}.c4dist{font-size:13px;color:var(--muted,#666);margin:4px 0 0}.c4cmp{display:none}@media (max-width:760px){.c4cmp{display:flex}}
.c4flag{margin-right:4px}.c4live{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
@media (max-width:420px){.hero h1{font-size:clamp(28px,8.4vw,40px);overflow-wrap:anywhere;hyphens:auto}}`;
